import math, random

def f(x): return 2**(-1/(x-1)**2)

def delta(eps):
    return 1/math.sqrt(math.log2(1/eps))

# Test: for random eps in (0,1), pick x with |x-1| < delta; check f(x) < eps
random.seed(0)
ok = True
for _ in range(20000):
    eps = 10**(-random.uniform(0.01, 12))   # eps in (1e-12, ~0.977)
    d = delta(eps)
    # x just inside the delta-neighborhood, and also near the boundary
    for frac in (0.5, 0.999, 0.99999):
        h = d*frac
        for x in (1+h, 1-h):
            if not (f(x) < eps):
                ok = False
                print("FAIL", eps, d, x, f(x))
print("all inside-neighborhood tests pass:", ok)

# Boundary sanity: at |x-1| = delta exactly, f(x) should equal eps
for eps in (0.5, 0.1, 1e-3, 1e-6, 1e-12):
    d = delta(eps)
    x = 1 + d
    print(f"eps={eps:g}  delta={d:.6g}  f(1+delta)={f(x):.6g}  (should equal eps)")

# Outside check: |x-1| slightly > delta should give f(x) > eps (equivalence)
for eps in (0.1, 1e-6):
    d = delta(eps)
    x = 1 + d*1.001
    print(f"eps={eps:g}  x=1+1.001*delta  f(x)={f(x):.6g} > eps? {f(x) > eps}")
"}

