from math import comb

def exact_profit(n, p=0.05, profit=59.5, ship=25, pen=200):
    # E[X^2] exact from binomial pmf
    EX2 = sum(x*x * comb(n,x)*(p**x)*((1-p)**(n-x)) for x in range(n+1))
    return profit*n - ship - pen*EX2

def formula_profit(n):
    return -0.5*n**2 + 50.0*n - 25

for n in range(45, 56):
    print(n, round(exact_profit(n),6), round(formula_profit(n),6))
"}

